 "content": "def transform(grid):
    """Recover the 8-marked patch by reflecting across the horizontal center."""
    h, w = len(grid), len(grid[0])
    cells = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 8]
    if not cells:
        return [row[:] for row in grid]
    r0, r1 = min(r for r, c in cells), max(r for r, c in cells)
    c0, c1 = min(c for r, c in cells), max(c for r, c in cells)
    out = [row[:] for row in grid]
    for r in range(r0, r1 + 1):
        for c in range(c0, c1 + 1):
            if grid[r][c] != 8:
                continue
            rr = h - 1 - r
            val = grid[rr][c]
            # The two central rows can mask their own reflected counterparts;
            # use the opposite edge of those rows as the available completion.
            if val == 8:
                val = grid[r][w - 1 - c]
            out[r][c] = val
    return [row[c0:c1 + 1] for row in out[r0:r1 + 1]]
